UPDATE "wa_conversations" AS "c" SET "assigned_user_id" = "p"."manager_user_id" FROM (SELECT DISTINCT ON ("customer_id") "customer_id", "manager_user_id" FROM "projects" WHERE "manager_user_id" IS NOT NULL ORDER BY "customer_id", "created_at" DESC) AS "p" WHERE "c"."customer_id" = "p"."customer_id" AND "c"."assigned_user_id" IS NULL;
